const overlap=(a,b)=>Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x)>0.01&&Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y)>0.01;
export function assertStaticHelpGeometry(controls,viewport,require44=false){
 const k=Math.min(viewport.w/L.width,(viewport.h-(viewport.safe??0))/L.height),rows=[];
 for(const [i,c] of controls.entries()){
  const css={width:c.rect.w*k,height:c.rect.h*k};
  if(require44)assert.ok(css.width>=43.99&&css.height>=43.99,`New help target below 44 CSS pixels: ${c.action.type}`);
  assert.ok(c.rect.x>=0&&c.rect.y>=0&&c.rect.x+c.rect.w<=L.width&&c.rect.y+c.rect.h<=L.height,'Touch target outside logical canvas');
  for(const other of controls.slice(i+1))assert.ok(!overlap(c.rect,other.rect),'Touch target overlap');rows.push({action:c.action,rect:c.rect,css});
 }
 return rows;
}
