  const driver=async(viewport={},storage=new Map(),epoch=Date.parse('2026-10-07T12:00:00Z'))=>{const h=attachGridWitness(attachPixelWitness(await createBoundFinalEconomyHost(binding,{...viewport,storage,epoch}))),inputs=[];for(const method of ['pointer','tap','drag']){const original=h[method];h[method]=(...args)=>{inputs.push({method,args,time:h.time});return original(...args);};}const d=new StaticHelpDriver(h,out,report.images,epoch);d.nativeInputs=inputs;drivers.push(d);return d;};
